<script setup lang="ts">
import { money, totals, today, effectiveStatus, needsFollowUp, type Quote, type Customer, type Line } from '~/utils/quotes'
const { data, loaded, storageError, saving, dirty, saveNow, refreshWorkspace, retrySave, reviseQuote } = useWorkspace()
async function reloadCloud() {
  const id = preview.value?.id
  await refreshWorkspace()
  if (id) preview.value = data.value.quotes.find(q => q.id === id) || null
}
async function logout() {
  try { await saveNow(); await $fetch('/api/auth/logout', { method: 'POST' }); clearNuxtState(['workspace', 'workspace-loaded', 'workspace-version', 'workspace-dirty']); await navigateTo('/login') }
  catch (e: any) { notify(e.data?.statusMessage || e.message || 'Unable to sign out. Export pending changes first.') }
}
async function saveProfile() { try { await saveNow(); notify('Business profile saved to the cloud') } catch (e: any) { notify(e.data?.statusMessage || e.message) } }
const editingQuoteId = ref('')
function editDraft(q: Quote) {
  if (q.status !== 'Draft') return
  editingQuoteId.value = q.id
  Object.assign(quoteForm, JSON.parse(JSON.stringify(q)), { discount: q.discount / 100 })
  preview.value = null; modal.value = 'quote'
}
function revision(q: Quote) { const copy = reviseQuote(q); editDraft(copy) }
const section = ref('Overview')
const search = ref('')
const filter = ref('All quotes')
const mobileMenu = ref(false)
const toast = ref('')
let toastTimer: ReturnType<typeof setTimeout>
function notify(message: string) { toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => { toast.value = '' }, 4500) }
onUnmounted(() => clearTimeout(toastTimer))
const nav = [{ name: 'Overview', icon: 'grid' }, { name: 'Quotes', icon: 'file' }, { name: 'Customers', icon: 'users' }, { name: 'Services', icon: 'briefcase' }, { name: 'Follow-ups', icon: 'clock' }]
function navigate(name: string) { section.value = name; search.value = ''; mobileMenu.value = false }
const customer = (id: string) => data.value.customers.find(c => c.id === id)
const quoteTotal = (q: Quote) => totals(q.items, q.discount, q.tax).total
const pending = computed(() => data.value.quotes.filter(q => effectiveStatus(q) === 'Sent'))
const accepted = computed(() => data.value.quotes.filter(q => q.status === 'Accepted'))
const due = computed(() => data.value.quotes.filter(q => needsFollowUp(q)).sort((a, b) => a.followUp.localeCompare(b.followUp)))
const scheduled = computed(() => pending.value.filter(q => q.followUp).sort((a, b) => a.followUp.localeCompare(b.followUp)))
const acceptedValue = computed(() => accepted.value.reduce((sum, q) => sum + quoteTotal(q), 0))
const pendingValue = computed(() => pending.value.reduce((sum, q) => sum + quoteTotal(q), 0))
const acceptanceRate = computed(() => {
  const decided = data.value.quotes.filter(q => ['Accepted', 'Declined'].includes(q.status))
  return decided.length ? Math.round(accepted.value.length / decided.length * 100) : 0
})
const quotes = computed(() => data.value.quotes.filter(q => {
  const text = `${q.id} ${q.title} ${customer(q.customerId)?.name}`.toLowerCase()
  return text.includes(search.value.toLowerCase()) && (filter.value === 'All quotes' || effectiveStatus(q) === filter.value)
}).sort((a,b) => b.id.localeCompare(a.id, undefined, { numeric: true })))
const customers = computed(() => data.value.customers.filter(c => `${c.name} ${c.company}`.toLowerCase().includes(search.value.toLowerCase())))
const displayDate = (date: string) => date ? new Intl.DateTimeFormat('en-PH', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'Asia/Manila' }).format(new Date(`${date}T12:00:00+08:00`)) : 'Not scheduled'
const initials = (name = '') => name.split(' ').map(n => n[0]).slice(0, 2).join('')
const modal = ref<'quote' | 'customer' | 'service' | null>(null)
const preview = ref<Quote | null>(null)
const dialogRef = ref<HTMLElement | null>(null)
let previousFocus: HTMLElement | null = null
watch(() => !!modal.value || !!preview.value, async (open) => {
  if (!import.meta.client) return
  document.body.style.overflow = open ? 'hidden' : ''
  if (open) { previousFocus = document.activeElement as HTMLElement; await nextTick(); dialogRef.value?.focus() }
  else previousFocus?.focus()
})
function trapFocus(event: KeyboardEvent) {
  if (event.key === 'Escape') { modal.value = null; preview.value = null; return }
  if (event.key !== 'Tab') return
  const nodes = dialogRef.value?.querySelectorAll<HTMLElement>('button:not([disabled]), input, select, textarea, [tabindex="0"], a[href]')
  if (!nodes?.length) return
  const first = nodes[0]!, last = nodes[nodes.length - 1]!
  if (event.shiftKey && (document.activeElement === first || document.activeElement === dialogRef.value)) { event.preventDefault(); last.focus() }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus() }
}
const quoteForm = reactive({ customerId: '', title: '', expires: '', followUp: '', discount: 0, tax: 0, notes: '', items: [] as Line[] })
const formError = ref('')
const calculated = computed(() => { try { return totals(quoteForm.items, Math.round(Number(quoteForm.discount) * 100), Number(quoteForm.tax)) } catch { return null } })
function newQuote() {
  if (!loaded.value) { notify('Wait for the cloud workspace to load.'); return }
  editingQuoteId.value = ''
  const d = new Date(`${today()}T12:00:00Z`); d.setUTCDate(d.getUTCDate() + 14)
  Object.assign(quoteForm, { customerId: data.value.customers[0]?.id || '', title: '', expires: d.toISOString().slice(0,10), followUp: '', discount: 0, tax: 0, notes: '', items: [] })
  addLine(); formError.value = ''; modal.value = 'quote'
}
function addLine() { const s = data.value.services[0]; quoteForm.items.push({ name: s?.name || '', quantity: 1, price: s?.price || 0 }) }
function chooseService(event: Event, index: number) { const service = data.value.services.find(s => s.id === (event.target as HTMLSelectElement).value); if (service) quoteForm.items[index] = { name: service.name, quantity: 1, price: service.price } }
function updatePrice(event: Event, item: Line) { item.price = Math.round(Number((event.target as HTMLInputElement).value) * 100) }
function saveQuote() {
  if (!quoteForm.items.length || !calculated.value || quoteForm.items.some(i => !i.name.trim()) || !data.value.customers.some(c => c.id === quoteForm.customerId)) { formError.value = 'Choose a customer and add valid services, quantities, and prices.'; return }
  if (quoteForm.expires < today()) { formError.value = 'The expiry date must be today or later.'; return }
  const sequence = Math.max(1000, ...data.value.quotes.map(q => Number(q.id.replace('QF-', '')) || 0)) + 1
  const q: Quote = { ...JSON.parse(JSON.stringify(quoteForm)), id: editingQuoteId.value || `QF-${sequence}`, title: quoteForm.title.trim(), discount: Math.round(Number(quoteForm.discount) * 100), tax: Number(quoteForm.tax), created: today(), status: 'Draft' }
  const existing = data.value.quotes.findIndex(item => item.id === editingQuoteId.value)
  if (existing >= 0) data.value.quotes.splice(existing, 1, q); else data.value.quotes.unshift(q)
  modal.value = null; section.value = 'Quotes'; preview.value = q; notify('Quote saved as a draft')
}
const customerForm = reactive({ name: '', company: '', email: '', phone: '', address: '' })
function newCustomer() { if (!loaded.value) return; Object.assign(customerForm, { name: '', company: '', email: '', phone: '', address: '' }); modal.value = 'customer' }
function saveCustomer() { const c: Customer = { ...customerForm, name: customerForm.name.trim(), id: crypto.randomUUID() }; if (!c.name) return; data.value.customers.push(c); modal.value = null; notify('Customer added') }
const serviceForm = reactive({ name: '', unit: 'job', price: 0 })
function newService() { if (!loaded.value) return; Object.assign(serviceForm, { name: '', unit: 'job', price: 0 }); modal.value = 'service' }
function saveService() { if (!serviceForm.name.trim() || !Number.isFinite(serviceForm.price) || serviceForm.price < 0) return; data.value.services.push({ ...serviceForm, name: serviceForm.name.trim(), id: crypto.randomUUID(), price: Math.round(serviceForm.price * 100) }); modal.value = null; notify('Service added') }
async function copyFollowUp(q: Quote) {
  const message = `Hi ${customer(q.customerId)?.name || 'there'}, just following up on ${q.id} for ${q.title} (${money(quoteTotal(q))}). Do you have any questions or would you like to schedule the service? Thank you, ${data.value.business.name}.`
  try { await navigator.clipboard.writeText(message); notify('Follow-up copied. Review it, then send it to your customer.') } catch { notify('Clipboard unavailable. You can copy a message from the quote preview.') }
}
const templateLanguage = ref('English')
const message = computed(() => !preview.value ? '' : templateLanguage.value === 'Filipino' ? `Kumusta ${customer(preview.value.customerId)?.name}! Narito ang quotation ${preview.value.id} para sa ${preview.value.title}. Ang kabuuan ay ${money(quoteTotal(preview.value))}. Pakisabi kung may tanong kayo. Salamat! — ${data.value.business.name}` : `Hi ${customer(preview.value.customerId)?.name}! Here is quote ${preview.value.id} for ${preview.value.title}. The total is ${money(quoteTotal(preview.value))}. Please let us know if you have any questions. Thank you! — ${data.value.business.name}`)
async function copyMessage() { try { await navigator.clipboard.writeText(message.value); notify('Message copied') } catch { notify('Please select and copy the message below.') } }
function setStatus(q: Quote, status: Quote['status']) { q.status = status; notify(`Quote marked ${status.toLowerCase()}`) }
function printQuote() { window.print() }
function exportData() {
  const url = URL.createObjectURL(new Blob([JSON.stringify(data.value, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = url; a.download = `quotefollow-${today()}.json`; a.click(); URL.revokeObjectURL(url); notify('Workspace exported')
}
</script>

<template>
  <div class="workspace">
    <button v-if="mobileMenu" class="nav-scrim" aria-label="Close navigation" @click="mobileMenu = false" />
    <aside :class="['sidebar', { 'is-open': mobileMenu }]">
      <a href="#" class="brand" @click.prevent="navigate('Overview')"><span class="brand-mark"><AppIcon name="check" :size="24" /></span><span>QuoteFollow<span class="brand-ph">PH</span></span></a>
      <div class="business-switch"><span class="business-avatar">{{ initials(data.business.name) || 'QF' }}</span><div><strong>{{ data.business.name }}</strong><small>Business workspace</small></div><AppIcon name="chevron" :size="14" /></div>
      <span class="nav-label">WORKSPACE</span>
      <nav aria-label="Main navigation"><button v-for="item in nav" :key="item.name" :class="['nav-item', { active: section === item.name }]" :aria-current="section === item.name ? 'page' : undefined" @click="navigate(item.name)"><AppIcon :name="item.icon" /><span>{{ item.name }}</span><span v-if="item.name === 'Follow-ups' && due.length" class="nav-count">{{ due.length }}</span></button></nav>
      <div class="sidebar-bottom"><div class="tip-card"><span class="tip-icon"><AppIcon name="spark" :size="18" /></span><strong>A little follow-up goes far.</strong><p>Keep the conversation going and turn more quotes into booked jobs.</p><button @click="navigate('Follow-ups')">View follow-ups <AppIcon name="arrow" :size="15" /></button></div><button :class="['nav-item', { active: section === 'Settings' }]" @click="navigate('Settings')"><AppIcon name="settings" />Settings</button><div class="profile"><span class="avatar">{{ initials(data.business.owner) }}</span><div><strong>{{ data.business.owner }}</strong><small>Business owner</small></div><span class="online-dot" /></div></div>
    </aside>

    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-toggle" aria-label="Open navigation" @click="mobileMenu = true"><AppIcon name="menu" /></button><span>Workspace</span><AppIcon name="chevron" :size="13" /><strong>{{ section }}</strong></div><div class="topbar-right"><span class="account-pill"><span /> Cloud account</span><button class="text-link" @click="logout">Sign out</button><span class="topbar-divider" /><span class="avatar small">{{ initials(data.business.owner) }}</span></div></header>
      <main>
        <div v-if="storageError" class="warning" role="alert">{{ storageError }}<div  class="status-actions"><UiButton variant="outline" @click="retrySave">Retry save</UiButton><UiButton variant="outline" @click="exportData">Export backup</UiButton></div></div>
        <div v-if="!loaded" class="warning">Cloud workspace is loading. If it does not load, check the database migration and reload.</div>
        <div v-if="loaded && !data.business.name" class="notice">Welcome! Open Settings to add your business name and contact details, then add your services and first customer.</div>
        <div  class="sync-toolbar"><span>{{ saving ? 'Saving changes…' : dirty ? 'Unsaved changes' : loaded ? 'Cloud workspace loaded' : 'Loading…' }}</span><UiButton variant="outline" :disabled="saving || !loaded" @click="saveProfile">Save now</UiButton><UiButton variant="outline" :disabled="saving || dirty || !loaded" @click="reloadCloud().catch(e => notify(e.message))">Refresh responses</UiButton></div>
        <div class="page-heading"><div><span class="eyebrow">{{ section === 'Overview' ? 'YOUR BUSINESS, AT A GLANCE' : 'YOUR BUSINESS. CLEAR WORKFLOW.' }}</span><h1>{{ section === 'Overview' ? (data.business.owner ? `A fresh start, ${data.business.owner}.` : 'Welcome to your workspace.') : section === 'Settings' ? 'Your workspace' : section }}</h1><p>{{ section === 'Overview' ? 'A little less admin. A lot more room to grow.' : section === 'Quotes' ? 'From first estimate to your next booked job.' : section === 'Customers' ? 'Good relationships start with the details.' : section === 'Services' ? 'Your expertise, with clear and consistent pricing.' : section === 'Follow-ups' ? 'The next conversation could be your next booking.' : 'Make this space feel like your business.' }}</p></div><UiButton v-if="['Overview','Quotes'].includes(section)" @click="newQuote"><AppIcon name="plus" :size="17" /> Create quote</UiButton><UiButton v-else-if="section === 'Customers'" @click="newCustomer"><AppIcon name="plus" :size="17" /> Add customer</UiButton><UiButton v-else-if="section === 'Services'" @click="newService"><AppIcon name="plus" :size="17" /> Add service</UiButton></div>

        <template v-if="section === 'Overview'">
          <div class="stats-grid"><article class="stat-card"><div class="stat-label">Pending quote value <AppIcon name="file" :size="18" /></div><strong>{{ money(pendingValue) }}</strong><small><span class="mini-dot amber" />{{ pending.length }} quotes awaiting a decision</small></article><article class="stat-card"><div class="stat-label">Accepted quote value <AppIcon name="wallet" :size="18" /></div><strong>{{ money(acceptedValue) }}</strong><small><span class="mini-dot green" />{{ accepted.length }} accepted · not collected revenue</small></article><article class="stat-card"><div class="stat-label">Acceptance rate <AppIcon name="check" :size="18" /></div><strong>{{ acceptanceRate }}<span class="stat-unit">%</span></strong><small>Of accepted and declined quotes</small></article><article class="stat-card"><div class="stat-label">Follow-ups due <AppIcon name="clock" :size="18" /></div><strong>{{ due.length.toString().padStart(2, '0') }}</strong><button class="text-link" @click="navigate('Follow-ups')">A good time to reconnect <AppIcon name="arrow" :size="14" /></button></article></div>
          <section class="welcome-banner"><div><span class="banner-kicker"><AppIcon name="spark" :size="15" /> SMALL STEPS, MORE BOOKINGS</span><h2>Your next job starts with a great quote.</h2><p>Put your best foot forward with a clear, professional estimate.<br class="desktop-break"> We’ll help you keep the follow-up in sight.</p><UiButton variant="outline" @click="newQuote">Let’s create a quote <AppIcon name="arrow" :size="16" /></UiButton></div></section>
          <div class="overview-columns"><section class="panel"><div class="panel-heading"><div><h2>Recent quotes <span class="count">{{ data.quotes.length }}</span></h2><p>Your latest estimates, all in one place.</p></div><button class="text-link" @click="navigate('Quotes')">View all <AppIcon name="arrow" :size="15" /></button></div><div class="table-scroll"><table><thead><tr><th>QUOTE / CUSTOMER</th><th>AMOUNT</th><th>STATUS</th><th><span class="sr-only">Details</span></th></tr></thead><tbody><tr v-for="q in quotes.slice(0, 5)" :key="q.id"><td><button class="quote-title" @click="preview = q">{{ q.title }}</button><small>{{ q.id }} <span class="muted-separator">·</span> {{ customer(q.customerId)?.name }}</small></td><td class="amount">{{ money(quoteTotal(q)) }}</td><td><span :class="['badge', effectiveStatus(q).toLowerCase()]"><span />{{ effectiveStatus(q) }}</span></td><td><button class="icon-button" :aria-label="`Open ${q.id}`" @click="preview = q"><AppIcon name="chevron" :size="16" /></button></td></tr><tr v-if="!quotes.length"><td colspan="4" class="empty">Your first quote starts here. Create one above.</td></tr></tbody></table></div></section><section class="panel follow-panel"><div class="panel-heading"><div><h2>Time to follow up <span class="count warm">{{ due.length }}</span></h2><p>A friendly nudge makes a difference.</p></div><AppIcon name="clock" :size="19" /></div><div v-for="q in due.slice(0, 3)" :key="q.id" class="follow-card"><div class="follow-person"><span class="avatar soft">{{ initials(customer(q.customerId)?.name) }}</span><div><strong>{{ customer(q.customerId)?.name }}</strong><small>{{ q.title }}</small></div><span class="due-label">{{ q.followUp < today() ? 'Overdue' : 'Today' }}</span></div><div class="follow-meta"><span>{{ q.id }} <span>·</span> {{ money(quoteTotal(q)) }}</span><button class="text-link" @click="copyFollowUp(q)">Copy message <AppIcon name="arrow" :size="14" /></button></div></div><div v-if="!due.length" class="empty"><AppIcon name="check" :size="28" /><strong>You’re all caught up.</strong><p>No follow-ups due today.</p></div><div class="follow-footer"><span class="mini-dot green" /> A helpful reminder, never an automatic send.</div></section></div>
        </template>

        <section v-else-if="section === 'Quotes'" class="panel"><div class="table-toolbar"><label class="search-box"><AppIcon name="search" :size="17" /><input v-model="search" placeholder="Search quotes or customers…" aria-label="Search quotes"></label><select v-model="filter" aria-label="Filter quote status"><option v-for="s in ['All quotes','Draft','Sent','Accepted','Declined','Expired']" :key="s">{{ s }}</option></select></div><div class="table-scroll"><table><thead><tr><th>QUOTE / CUSTOMER</th><th>CREATED</th><th>AMOUNT</th><th>STATUS</th><th /></tr></thead><tbody><tr v-for="q in quotes" :key="q.id"><td><button class="quote-title" @click="preview = q">{{ q.title }}</button><small>{{ q.id }} · {{ customer(q.customerId)?.name }}</small></td><td>{{ displayDate(q.created) }}</td><td class="amount">{{ money(quoteTotal(q)) }}</td><td><span :class="['badge', effectiveStatus(q).toLowerCase()]"><span />{{ effectiveStatus(q) }}</span></td><td><button class="icon-button" :aria-label="`Open ${q.id}`" @click="preview = q"><AppIcon name="chevron" :size="16" /></button></td></tr><tr v-if="!quotes.length"><td colspan="5" class="empty">No matching quotes. Try another search or create a quote.</td></tr></tbody></table></div></section>

        <section v-else-if="section === 'Customers'" class="panel"><div class="table-toolbar"><label class="search-box"><AppIcon name="search" :size="17" /><input v-model="search" placeholder="Search customers…" aria-label="Search customers"></label></div><div class="table-scroll"><table><thead><tr><th>CUSTOMER</th><th>CONTACT</th><th>LOCATION</th><th>QUOTES</th></tr></thead><tbody><tr v-for="c in customers" :key="c.id"><td><div class="customer-cell"><span class="avatar soft">{{ initials(c.name) }}</span><div><strong>{{ c.name }}</strong><small>{{ c.company || 'Personal account' }}</small></div></div></td><td>{{ c.email || 'No email' }}<small>{{ c.phone || 'No phone added' }}</small></td><td>{{ c.address || 'No address added' }}</td><td>{{ data.quotes.filter(q => q.customerId === c.id).length }}</td></tr><tr v-if="!customers.length"><td colspan="4" class="empty">No matching customers. Add a customer to get started.</td></tr></tbody></table></div></section>

        <div v-else-if="section === 'Services'" class="service-grid"><article v-for="s in data.services" :key="s.id" class="panel service-card"><span class="service-icon"><AppIcon name="spark" :size="23" /></span><h2>{{ s.name }}</h2><p>Saved rate · adjustable on each quote</p><strong>{{ money(s.price) }}<small> / {{ s.unit }}</small></strong><UiButton variant="outline" @click="newQuote">Create a quote <AppIcon name="arrow" :size="15" /></UiButton></article><div v-if="!data.services.length" class="panel empty">Add your first service and save its price.</div></div>

        <section v-else-if="section === 'Follow-ups'" class="panel"><div class="panel-heading"><div><h2>Your next conversations</h2><p>{{ due.length }} due now · reminders stop when a quote is accepted, declined, or expired.</p></div></div><div v-for="q in scheduled" :key="q.id" class="follow-list-item"><span class="avatar soft">{{ initials(customer(q.customerId)?.name) }}</span><div class="follow-list-description"><button class="quote-title" @click="preview = q">{{ customer(q.customerId)?.name }}</button><small>{{ q.id }} · {{ q.title }} · {{ money(quoteTotal(q)) }}</small></div><span :class="['badge', needsFollowUp(q) ? 'sent' : 'draft']">{{ displayDate(q.followUp) }}</span><UiButton variant="outline" @click="copyFollowUp(q)"><AppIcon name="copy" :size="16" /> Copy message</UiButton></div><div v-if="!scheduled.length" class="empty">No follow-ups scheduled. Open a sent quote to add a reminder.</div></section>

        <template v-else-if="section === 'Settings'"><section class="panel settings-panel"><div class="panel-heading"><div><h2>Business profile</h2><p>Shown on your quote preview and printed documents.</p></div></div><form class="settings-form" @submit.prevent="saveProfile"><div class="form-grid"><label>Business name<input v-model="data.business.name" required maxlength="100"></label><label>Your first name<input v-model="data.business.owner" required maxlength="50"></label><label>Email<input v-model="data.business.email" type="email"></label><label>Phone<input v-model="data.business.phone" type="tel" placeholder="+63"></label><label class="span-two">Business address<input v-model="data.business.address"></label><label class="span-two checkbox-label"><input v-model="data.business.emailReminders" type="checkbox">Email me a daily summary of due follow-ups (requires configured email and scheduler).</label><label class="span-two">Quote terms<textarea v-model="data.business.terms" rows="3" maxlength="5000" placeholder="Payment terms, exclusions, and other policies" /></label></div><UiButton type="submit">Save profile</UiButton></form></section><section class="panel settings-panel"><div class="panel-heading"><div><h2>Workspace backup</h2><p>Export a copy of your cloud records.</p></div></div><div class="settings-form"><p>Keep an export before changing accounts or reloading unsaved changes. Configure services in your server environment to enable cloud features.</p><UiButton variant="outline" @click="exportData"><AppIcon name="download" :size="16" /> Export workspace JSON</UiButton></div></section><IntegrationSettings  /></template>
        <footer class="page-footer"><span>Made for fresh starts and growing businesses.</span><span><span class="mini-dot green" /> {{ saving ? 'Saving to cloud…' : dirty ? 'Unsaved changes' : loaded ? 'Cloud workspace' : 'Loading workspace…' }}</span></footer>
      </main>
    </div>

    <div v-if="modal || preview" class="modal-backdrop" @click.self="modal = null; preview = null"><section ref="dialogRef" class="dialog" :class="{ 'quote-preview': preview }" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1" @keydown="trapFocus"><div class="dialog-heading"><div><span class="eyebrow">{{ preview ? preview.id : 'A NEW BEGINNING' }}</span><h2 id="dialog-title">{{ preview ? preview.title : modal === 'quote' ? 'Create a quote' : modal === 'customer' ? 'Add customer' : 'Add service' }}</h2></div><button class="icon-button" aria-label="Close dialog" @click="modal = null; preview = null"><AppIcon name="close" /></button></div>
      <form v-if="modal === 'quote'" @submit.prevent="saveQuote"><div class="dialog-body"><div v-if="!data.customers.length" class="warning">Add a customer before creating a quote.</div><div class="form-grid"><label>Customer<select v-model="quoteForm.customerId" required><option value="" disabled>Select customer</option><option v-for="c in data.customers" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>Quote title<input v-model="quoteForm.title" required maxlength="120" placeholder="e.g. Condo deep cleaning"></label><label>Valid until<input v-model="quoteForm.expires" type="date" :min="today()" required></label><label>Follow-up date <span class="optional">optional</span><input v-model="quoteForm.followUp" type="date" :min="today()"></label></div><div class="form-section-heading"><h3>Services</h3><button type="button" class="text-link" @click="addLine"><AppIcon name="plus" :size="15" /> Add item</button></div><div v-for="(item, i) in quoteForm.items" :key="i" class="line-item"><label>Service<select aria-label="Choose saved service" @change="chooseService($event, i)"><option value="">Custom service</option><option v-for="s in data.services" :key="s.id" :value="s.id" :selected="s.name === item.name">{{ s.name }}</option></select><input v-model="item.name" required aria-label="Service description" placeholder="Service description"></label><label>Quantity<input v-model.number="item.quantity" type="number" min="0.01" max="1000000" step="0.01" required></label><label>Price (₱)<input :value="item.price / 100" type="number" min="0" max="100000000" step="0.01" required @input="updatePrice($event, item)"></label><button type="button" class="icon-button remove-item" :aria-label="`Remove item ${i + 1}`" @click="quoteForm.items.splice(i, 1)"><AppIcon name="close" :size="16" /></button></div><div class="form-grid"><label>Discount (₱)<input v-model.number="quoteForm.discount" type="number" min="0" max="100000000" step="0.01" required></label><label>Tax (%)<input v-model.number="quoteForm.tax" type="number" min="0" max="100" step="0.01" required></label><label class="span-two">Notes & inclusions<textarea v-model="quoteForm.notes" rows="3" placeholder="Describe what is included, access requirements, or payment terms." /></label></div><div class="quote-total"><span>Total estimate</span><strong>{{ calculated ? money(calculated.total) : 'Check amounts' }}</strong></div><p v-if="formError" class="form-error" role="alert">{{ formError }}</p></div><div class="dialog-footer"><UiButton variant="outline" @click="modal = null">Cancel</UiButton><UiButton type="submit">Save draft <AppIcon name="arrow" :size="16" /></UiButton></div></form>
      <form v-else-if="modal === 'customer'" @submit.prevent="saveCustomer"><div class="dialog-body form-grid"><label class="span-two">Full name<input v-model="customerForm.name" required maxlength="100"></label><label>Company <span class="optional">optional</span><input v-model="customerForm.company" maxlength="100"></label><label>Email<input v-model="customerForm.email" type="email"></label><label>Phone<input v-model="customerForm.phone" type="tel" placeholder="+63"></label><label>Service address<input v-model="customerForm.address"></label></div><div class="dialog-footer"><UiButton variant="outline" @click="modal = null">Cancel</UiButton><UiButton type="submit">Add customer</UiButton></div></form>
      <form v-else-if="modal === 'service'" @submit.prevent="saveService"><div class="dialog-body form-grid"><label class="span-two">Service name<input v-model="serviceForm.name" required maxlength="120"></label><label>Unit<select v-model="serviceForm.unit"><option v-for="unit in ['job','hour','sqm','seat','item']" :key="unit">{{ unit }}</option></select></label><label>Price per unit (₱)<input v-model.number="serviceForm.price" type="number" min="0" max="100000000" step="0.01" required></label></div><div class="dialog-footer"><UiButton variant="outline" @click="modal = null">Cancel</UiButton><UiButton type="submit">Save service</UiButton></div></form>
      <template v-else-if="preview"><div class="dialog-body"><div class="print-business"><span class="brand-mark"><AppIcon name="check" :size="24" /></span><div><h3>{{ data.business.name }}</h3><p>{{ data.business.address }}</p><p>{{ data.business.email }} {{ data.business.phone }}</p></div><span :class="['badge', effectiveStatus(preview).toLowerCase()]"><span />{{ effectiveStatus(preview) }}</span></div><div class="preview-meta"><div><small>PREPARED FOR</small><strong>{{ customer(preview.customerId)?.name }}</strong><p>{{ customer(preview.customerId)?.company }}</p><p>{{ customer(preview.customerId)?.address }}</p></div><div><small>QUOTE DETAILS</small><p>{{ preview.id }} · {{ displayDate(preview.created) }}</p><p>Valid until {{ displayDate(preview.expires) }}</p></div></div><table class="preview-table"><thead><tr><th>SERVICE</th><th>QTY</th><th>RATE</th><th>AMOUNT</th></tr></thead><tbody><tr v-for="(item, i) in preview.items" :key="i"><td>{{ item.name }}</td><td>{{ item.quantity }}</td><td>{{ money(item.price) }}</td><td>{{ money(Math.round(item.price * item.quantity)) }}</td></tr></tbody></table><div class="preview-totals"><p><span>Subtotal</span>{{ money(totals(preview.items).subtotal) }}</p><p><span>Discount</span>−{{ money(totals(preview.items, preview.discount).discount) }}</p><p><span>Tax ({{ preview.tax }}%)</span>{{ money(totals(preview.items, preview.discount, preview.tax).taxAmount) }}</p><div class="quote-total"><span>Total estimate</span><strong>{{ money(quoteTotal(preview)) }}</strong></div></div><div v-if="preview.notes" class="preview-notes"><h3>Notes & inclusions</h3><p>{{ preview.notes }}</p></div><div class="owner-controls"><div class="form-section-heading"><h3>Owner actions</h3><span class="optional">Owner-recorded actions</span></div><div class="status-actions"><UiButton v-if="preview.status === 'Draft'" variant="outline" @click="editDraft(preview)">Edit draft</UiButton><UiButton v-else variant="outline" @click="revision(preview)">Create revision</UiButton><UiButton v-if="preview.status === 'Draft'" @click="setStatus(preview, 'Sent')">Mark as sent</UiButton><template v-if="effectiveStatus(preview) === 'Sent'"><UiButton @click="setStatus(preview, 'Accepted')"><AppIcon name="check" :size="16" /> Record acceptance</UiButton><UiButton variant="outline" @click="setStatus(preview, 'Declined')">Record decline</UiButton></template></div><label v-if="effectiveStatus(preview) === 'Sent'" class="reminder-input">Follow-up reminder<input v-model="preview.followUp" type="date" :min="today()"></label><div class="form-section-heading"><h3>Message template</h3><select v-model="templateLanguage" aria-label="Message language"><option>English</option><option>Filipino</option></select></div><textarea :value="message" rows="4" aria-label="Message template" readonly /><p class="helper">Editable templates are available without AI. Copy and send after reviewing.</p><UiButton variant="outline" @click="copyMessage"><AppIcon name="copy" :size="16" /> Copy message</UiButton><QuoteActions :quote="preview"  :save-workspace="saveNow" :refresh-workspace="reloadCloud" /></div></div><div class="dialog-footer"><UiButton variant="outline" @click="preview = null">Close</UiButton><UiButton @click="printQuote"><AppIcon name="download" :size="16" /> Print / Save PDF</UiButton></div></template>
    </section></div>
    <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><span class="toast-check"><AppIcon name="check" :size="17" /></span>{{ toast }}</div></Transition>
  </div>
</template>
